    );

CREATE FUNCTION protect_project_kind()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.project_kind IS DISTINCT FROM OLD.project_kind THEN
        RAISE EXCEPTION 'project kind is immutable' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;

