    CONSTRAINT project_commerce_workflow_bindings_profile_hash_check CHECK (video_profile_snapshot_hash ~ '^[0-9a-f]{64}$'),
    CONSTRAINT project_commerce_workflow_bindings_lifecycle_check CHECK (
