-- migration 000058_commerce_timeline_identity_repair.sql sha256:5577d7306bcf70c6bf840c4c10fe601eeac8b528a076a153ab0865120a75fdbe
BEGIN;
SET search_path TO public;

CREATE OR REPLACE FUNCTION validate_commerce_timeline_overlay_identity()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    clip_shot UUID;
    clip_project UUID;
    clip_generation UUID;
    shot_unit UUID;
    shot_generation UUID;
BEGIN
    IF NEW.timeline_clip_id IS NOT NULL THEN
        SELECT clip.storyboard_shot_id, clip.project_id, clip.production_generation_id
          INTO clip_shot, clip_project, clip_generation
        FROM timeline_clips clip
        WHERE clip.id = NEW.timeline_clip_id
          AND clip.timeline_id = NEW.timeline_id;

        IF clip_project IS NULL
           OR clip_project IS DISTINCT FROM NEW.project_id
           OR clip_generation IS DISTINCT FROM NEW.production_generation_id
           OR clip_shot IS DISTINCT FROM NEW.storyboard_shot_id THEN
            RAISE EXCEPTION 'commerce timeline overlay clip identity mismatch' USING ERRCODE = '23514';
        END IF;
    END IF;

    IF NEW.storyboard_shot_id IS NOT NULL THEN
        SELECT contract.script_unit_id, contract.script_unit_generation_id
          INTO shot_unit, shot_generation
        FROM storyboard_shots shot
        JOIN commerce_shot_contracts contract
          ON contract.storyboard_shot_id = shot.id
         AND contract.commerce_storyboard_plan_id = shot.commerce_storyboard_plan_id
         AND contract.organization_id = shot.organization_id
         AND contract.project_id = shot.project_id
        WHERE shot.id = NEW.storyboard_shot_id
          AND shot.organization_id = NEW.organization_id
          AND shot.project_id = NEW.project_id
          AND shot.production_generation_id = NEW.production_generation_id
          AND shot.deleted_at IS NULL;

        IF shot_unit IS NULL
           OR shot_unit IS DISTINCT FROM NEW.commerce_script_unit_id
           OR shot_generation IS DISTINCT FROM NEW.commerce_script_unit_generation_id THEN
            RAISE EXCEPTION 'commerce timeline overlay shot identity mismatch' USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;
COMMIT;

-- migration 000059_commerce_unit_generation_revision.sql sha256:389c112c92044660e6502abb77f90f2674b30db031c5e29c85cc914afa5ab915
BEGIN;
SET search_path TO public;

ALTER TABLE commerce_script_unit_generations
    ADD COLUMN script_unit_revision BIGINT;

WITH observed_revisions AS MATERIALIZED (
    SELECT workflow.input #>> '{identity,scriptUnitGenerationId}' AS generation_id,
           (workflow.input #>> '{identity,scriptUnitRevision}')::BIGINT AS script_unit_revision
    FROM workflow_runs workflow
    WHERE workflow.input #>> '{identity,scriptUnitGenerationId}' IS NOT NULL
      AND workflow.input #>> '{identity,scriptUnitRevision}' ~ '^[1-9][0-9]{0,17}$'
),
frozen_revisions AS (
    SELECT generation_id, min(script_unit_revision) AS script_unit_revision
    FROM observed_revisions
    GROUP BY generation_id
)
UPDATE commerce_script_unit_generations generation
SET script_unit_revision = COALESCE(
    (
        SELECT frozen.script_unit_revision
        FROM frozen_revisions frozen
        WHERE frozen.generation_id = generation.id::text
    ),
    unit.revision
)
FROM commerce_script_units unit
WHERE unit.id = generation.script_unit_id
  AND unit.product_id = generation.product_id
  AND unit.organization_id = generation.organization_id
  AND unit.project_id = generation.project_id;

ALTER TABLE commerce_script_unit_generations
    ALTER COLUMN script_unit_revision SET NOT NULL,
    ADD CONSTRAINT commerce_unit_generations_script_unit_revision_check
        CHECK (script_unit_revision > 0);

CREATE FUNCTION protect_commerce_unit_generation_revision()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.script_unit_revision IS DISTINCT FROM OLD.script_unit_revision THEN
        RAISE EXCEPTION 'commerce script unit generation revision is immutable' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER commerce_unit_generations_revision_immutable
BEFORE UPDATE OF script_unit_revision ON commerce_script_unit_generations
FOR EACH ROW EXECUTE FUNCTION protect_commerce_unit_generation_revision();
COMMIT;

-- migration 000060_commerce_multilingual_workflow_v2.sql sha256:bbca5a502b65f677cfbd6c05a65fe77443cb6d1fb5a746a1d84c845ecabbe4aa
BEGIN;
SET search_path TO public;

-- Keep the published v1 prompt addressable by immutable workflow snapshots,
-- but make the spoken-language-aware resolver the active system version.
UPDATE prompt_versions
SET status = 'archived'
WHERE id = md5('cineweave:commerce-prompt-version:commerce_language_resolver:1')::uuid
  AND status = 'active';

WITH source_prompt AS (
    SELECT
        template.id AS template_id,
        version.variables_schema,
        version.metadata
    FROM prompt_templates template
    JOIN prompt_versions version
      ON version.id = md5('cineweave:commerce-prompt-version:commerce_language_resolver:1')::uuid
    WHERE template.organization_id IS NULL
      AND template.template_key = 'commerce_language_resolver'
      AND template.id = COALESCE(version.template_id, version.prompt_template_id)
), resolver AS (
    SELECT
        $prompt$
你是 CineWeave 带货视频语言解析器。根据冻结的单个脚本单元、用户语言模式、模板允许的 BCP 47 locale 和目标平台，自动确定实际口播语言。

规则：
1. 输出必须是一个 JSON 对象，不得输出 Markdown、解释文字或代码围栏。
2. sourceLanguage 和 targetLanguage 必须是输入允许的规范 BCP 47 tag；不得发明 locale。
3. explicit 模式下，targetLanguage 必须逐字等于用户指定值。
4. auto 模式不允许要求用户确认。必须在最多 3 轮内给出一个可执行结果；无法可靠判断时返回契约错误供下一轮修正。
5. 语言判断优先级：明确的 VOICEOVER/NARRATION/旁白/口播语言标注 > 实际台词和旁白文本 > 屏幕文字 > 场景描述和制作指令。英文场景说明不能覆盖明确标注为 Malay、Bahasa Melayu、中文等语言的口播。
6. 脚本可包含多种书写语言。languageComposition 可以为 mixed，但 targetLanguage 必须表示观众实际听到的主要口播语言，needsUserConfirmation 必须为 false。
7. 不得翻译、改写或补充脚本，不得读取其他脚本单元。

严格输出契约：
{"contractVersion":"commerce-language-resolution/v1","sourceLanguage":"ms-MY","targetLanguage":"ms-MY","confidence":0.98,"languageComposition":"mixed","needsUserConfirmation":false,"reasoning":"脚本明确标注 VOICEOVER (Malay)，实际口播为马来语，英文仅用于场景说明","issues":[]}

输入：{{ input.context }}
