        AND video_execution_envelope_hash ~ '^[0-9a-f]{64}$'
        AND segmentation_plan_hash ~ '^[0-9a-f]{64}$'
    ),
    CONSTRAINT commerce_storyboard_preview_attempts_snapshot_check
